def resolve(path, cwd, links):
    # Validate cwd is canonical absolute
    if not cwd.startswith('/') or cwd != cwd.rstrip('/') or cwd == '':
        return None

    # Handle None or empty path
    if path is None or path == '':
        return None

    # Start with cwd if path is relative, otherwise start with /
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    link_count = 0
    max_links = 8

    while True:
        # Split remaining path into components
        components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                continue

            # Append component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if candidate is a symlink
            if candidate in links:
                # Check link count
                if link_count >= max_links:
                    return None

                link_count += 1
                target = links[candidate]

                # Resolve target relative to the directory containing the link
                if target.startswith('/'):
                    # Absolute target
                    current = '/'
                    remaining = target[1:]
                else:
                    # Relative target - relative to directory containing the link
                    if candidate == '/':
                        link_dir = '/'
                    else:
                        link_dir = candidate.rsplit('/', 1)[0]
                        if link_dir == '':
                            link_dir = '/'

                    current = link_dir
                    remaining = target

                # Break inner loop and restart with new remaining
                break
            else:
                # Not a symlink, just move current to candidate
                current = candidate
        else:
            # We processed all components without finding a symlink
            break

        # If we broke out of the for loop due to a symlink, continue the while loop
        # If we completed the for loop normally, we'll exit the while loop

    # Validate the final result is canonical (no trailing slash except '/')
    if current == '/':
        return '/'
    elif current.endswith('/'):
        return None
    else:
        return current

